for(const f of foes){f.phase+=dt*4;const a=Math.atan2(player.y-f.y,player.x-f.x);f.x+=Math.cos(a)*f.speed*dt;f.y+=Math.sin(a)*f.speed*dt;f.hit=Math.max(0,f.hit-dt);if(Math.hypot(player.x-f.x,player.y-f.y)<player.r+f.r&&player.invuln<=0){player.hp--;player.invuln=1.15;shake=12;flash=.65;burst(player.x,player.y,'#ff648c',13);f.x-=Math.cos(a)*38;f.y-=Math.sin(a)*38;updateHud();if(player.hp<=0){end();return}}}
