for(const b of bullets){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;for(const f of foes){if(f.hp>0&&Math.hypot(b.x-f.x,b.y-f.y)<f.r+4){b.life=0;f.hp--;f.hit=.09;if(f.hp<=0){score+=f.fast?15:25;burst(f.x,f.y,f.fast?'#ff648c':'#a88bff',10);if(Math.random()<.78)shard(f.x,f.y);if(Math.random()<.1)shard(f.x,f.y,2)}}}}
