for(const e of entities){e.life-=dt;e.spin+=dt*3;e.x+=e.vx*dt;e.y+=e.vy*dt;e.vx*=Math.pow(.08,dt);e.vy*=Math.pow(.08,dt);let d=Math.hypot(player.x-e.x,player.y-e.y);if(d<125){const a=Math.atan2(player.y-e.y,player.x-e.x),pull=(1-d/125)*290;e.vx+=Math.cos(a)*pull*dt;e.vy+=Math.sin(a)*pull*dt}if(d<player.r+e.r+2){e.life=0;score+=e.n===2?50:50;burst(e.x,e.y,'#62f5e6',7)}}entities=entities.filter(e=>e.life>0);
