function path(x,y,r,sides,rot=0){ctx.beginPath();for(let i=0;i<sides;i++){const a=rot+i*Math.PI*2/sides,px=x+Math.cos(a)*r,py=y+Math.sin(a)*r;i?ctx.lineTo(px,py):ctx.moveTo(px,py)}ctx.closePath()}
function render(t){ctx.clearRect(0,0,W,H);const ox=shake?rand(-shake,shake):0,oy=shake?rand(-shake,shake):0;ctx.save();ctx.translate(ox,oy);
const bg=ctx.createRadialGradient(W*.5,H*.48,20,W*.5,H*.5,Math.max(W,H)*.78);bg.addColorStop(0,'#111a30');bg.addColorStop(.58,'#0a1121');bg.addColorStop(1,'#080c18');ctx.fillStyle=bg;ctx.fillRect(-20,-20,W+40,H+40);
ctx.save();ctx.strokeStyle='rgba(126,158,221,.035)';ctx.lineWidth=1;for(let x=0;x<W;x+=48){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<H;y+=48){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.restore();for(const s of stars){const glow=.45+.45*Math.sin(t*.001*s.z+s.p);ctx.fillStyle=`rgba(190,216,255,${glow*.62})`;ctx.beginPath();ctx.arc(s.x,s.y,s.z*1.15,0,Math.PI*2);ctx.fill();if(s.z>.85){ctx.strokeStyle=`rgba(98,245,230,${glow*.26})`;ctx.beginPath();ctx.moveTo(s.x-3,s.y);ctx.lineTo(s.x+3,s.y);ctx.moveTo(s.x,s.y-3);ctx.lineTo(s.x,s.y+3);ctx.stroke()}}
// distant rotating signal rings
ctx.save();ctx.translate(W/2,H/2);ctx.rotate(t*.000035);ctx.strokeStyle='rgba(98,245,230,.055)';ctx.setLineDash([3,14]);[90,140,210].forEach(r=>{ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.stroke()});ctx.restore();
for(const e of entities){ctx.save();ctx.translate(e.x,e.y);ctx.rotate(e.spin);ctx.shadowBlur=18;ctx.shadowColor='#62f5e6';ctx.strokeStyle='rgba(98,245,230,.38)';ctx.lineWidth=1;path(0,0,12,4,Math.PI/4);ctx.stroke();ctx.fillStyle='#62f5e6';path(0,0,5,4,Math.PI/4);ctx.fill();ctx.restore()}
for(const b of bullets){ctx.save();ctx.strokeStyle='#aefcf3';ctx.shadowColor='#62f5e6';ctx.shadowBlur=12;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(b.x-b.vx*.028,b.y-b.vy*.028);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.restore()}
for(const f of foes){ctx.save();ctx.translate(f.x,f.y);ctx.rotate(f.phase*.14);ctx.shadowBlur=f.hit?20:14;ctx.shadowColor=f.fast?'#ff648c':'#a88bff';ctx.fillStyle=f.hit?'#fff':f.fast?'#ff648c':'#9a77ff';ctx.strokeStyle=f.fast?'#ff9bb2':'#cfbdff';ctx.lineWidth=1.2;path(0,0,f.r, f.fast?3:6,Math.PI/6);ctx.fill();ctx.stroke();ctx.globalAlpha=.32;path(0,0,f.r+5,f.fast?3:6,Math.PI/6);ctx.stroke();ctx.restore()}
if(player){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.angle);const blink=player.invuln>0&&Math.floor(t/65)%2===0;ctx.globalAlpha=blink?.45:1;ctx.shadowColor='#62f5e6';ctx.shadowBlur=player.dash>0?28:17;ctx.fillStyle='#d8fff9';ctx.strokeStyle='#62f5e6';ctx.lineWidth=1.4;ctx.beginPath();ctx.moveTo(15,0);ctx.lineTo(-9,-9);ctx.lineTo(-5,0);ctx.lineTo(-9,9);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#62f5e6';ctx.beginPath();ctx.moveTo(-7,-3);ctx.lineTo(-16,0);ctx.lineTo(-7,3);ctx.fill();ctx.restore()}
for(const p of bits){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=8;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.shadowBlur=0;ctx.restore();if(flash>0){ctx.fillStyle=`rgba(255,76,115,${flash*.16})`;ctx.fillRect(0,0,W,H)}
}
function frame(t){const dt=Math.min(.034,(t-last)/1000||0);last=t;update(dt);render(t);requestAnimationFrame(frame)}
reset();showOverlay('menu');requestAnimationFrame(frame);
})();
</script>
</body>
